contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;
        uint beforeRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(
            reverted &&
            c.getBalance(address(this)) == beforeRecorded &&
            address(c).balance == beforeBal
        );
    }

    // Reject Ether so the withdrawal's transfer to msg.sender fails.
    receive() external payable {
        revert("reject");
    }
}

