        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        try c.addToBalance{value: amount}() {} catch { return; }
        uint beforeBal = address(c).balance;
        uint256 beforeRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted &&
            c.getBalance(address(this)) == beforeRecorded &&
            address(c).balance == beforeBal);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
